#include <stdio.h>

int main(void)
{
    int n = 3;
    for (int row = 1; row <= n; row++) {
        for (int col = 1; col <= row; col++) {
            printf("*");
        }
        puts("");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 2;
    for (int row = 1; row <= n; row++) {
        for (int space = 0; space < n - row; space++) {
            printf(" ");
        }
        for (int star = 0; star < 2 * row - 1; star++) {
            printf("*");
        }
        puts("");
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int next = 1;
    for (int row = 1; row <= 2; row++) {
        for (int col = 1; col <= row; col++) {
            printf("%d", next++);
        }
        puts("");
    }
    return 0;
}

